local _, WFJ = ...
WFJ.Data.add("book", {
  ["b708e72a354af1c8"] = { "Capitolo 1 - La prima linea\n\nLe prime linee delle difese dei Lupi Bianchi sono formate da guerrieri dei Lupi Bianchi. I guerrieri vengono mandati in prima linea dalla fortezza del capitano Galvangar: il ⟦Iceblood Garrison=Presidio di Brinarossa⟧. Il modo più efficace per eliminare questo strato delle difese è distruggere il ⟦Iceblood Garrison=Presidio di Brinarossa⟧.\n\nAssedia la fortezza e annienta il capitano Galvangar. Fatto questo, le prime linee crolleranno.", "." },
  ["b7117ecfd2c613eb"] = { "Infine, devo ribadire la mia richiesta di polvere esplosiva. Le mie scorte sono scarsissime, e questo ostacola gravemente la riuscita degli scavi. Mi era stato detto che un rifornimento di polvere esplosiva era in arrivo, ma non l'ho ancora ricevuto.\n\nPosso chiedere a cosa sia dovuto il ritardo?\n\nCon ossequio,\nProspettore Darteus Ironband", "." },
  ["b72b1a85e4732ac1"] = { "Arellas Fireleaf\nSommo mago della ⟦Scarlet Crusade=Crociata Scarlatta⟧ \nCittadino di Quel'Thalas \nAvvinto in un eterno combattimento con il negromante Diesalven", "." },
  ["b72e6551ffdbc464"] = { "Nemmeno con l'aiuto dell'alta elfa Alleria Windrunner, del nano Kurdran Wildhammer e del soldato veterano Danath Trollbane Khadgar riuscì a impedire a Ner'zhul di aprire i suoi portali verso altri mondi.", "." },
  ["b78616c397be0763"] = { "Grish,\n\nLa tua richiesta di un periodo di congedo è stata accolta. Ti mando un guerriero tauren di riserva a sorvegliare il tuo posto mentre ti prendi del tempo da passare con la tua famiglia. Rientra in servizio tra una settimana!\n\n-Maggran Earthbinder", "." },
  ["b7cefdf73e27dadc"] = { "La soluzione, però, è piuttosto semplice. Usando polpa di legno come assorbente, possiamo combinare tracce di nitroglicerina con nitrato di sodio e ottenere una potente carica esplosiva, in grado di aprirsi un varco anche nelle masse più compatte.\n\nIl lavoro sarà rumoroso e molesto, ma la nostra ricerca è di gran lunga più importante della tranquillità degli abitanti del luogo. Anzi, abbiamo già dovuto cacciare dalla zona una banda di uomini-toro che si stava rivelando una seccatura.", "." },
  ["b7de9bc46d54cfdf"] = { "Nonostante la dura educazione, il giovane Thrall crebbe forte e di mente pronta, e sapeva in cuor suo che la vita da schiavo non faceva per lui. Diventando adulto, apprese del suo popolo, gli orchi, che non aveva mai incontrato: dopo la sconfitta, la maggior parte di loro era stata rinchiusa nei campi di internamento. Si diceva che Doomhammer, il capo degli orchi, fosse fuggito da Lordaeron e si fosse nascosto. Un solo clan ribelle agiva ancora in segreto, cercando di sfuggire agli occhi vigili dell'⟦Alliance=Alleanza⟧.", "." },
  ["b7efed7943da537d"] = { "Sia Ajeck sia sir Erlgadin stavano pronti, i fucili puntati sulla fitta vegetazione ai piedi degli alberi ondeggianti. Il sole di mezzogiorno ci batteva addosso, pesante. Un lento rivolo di sudore scese dalla tempia di Erlgadin mentre tirava indietro il cane. Allo scatto, la folta vegetazione si aprì e una grossa pantera nera, un esemplare splendido, schizzò fuori nella pianura.", "." },
})
